<template>
  <section class="account-tutorial-page">
    <header class="account-tutorial-intro">
      <div><small>Lorana Tales 学院</small><h2>基本使用教程</h2></div>
      <div class="account-tutorial-progress"><strong>{{ catalog?.tutorials.length || 0 }}</strong><span>个短教程</span></div>
    </header>
    <div v-if="loading" class="account-tutorial-state"><i></i><span>正在整理教室……</span></div>
    <div v-else-if="error" class="account-tutorial-state is-error"><strong>教程暂时没有打开</strong><span>{{ error }}</span><button type="button" @click="loadCatalog">重试</button></div>
    <template v-else>
      <nav class="account-tutorial-categories" aria-label="教程分类">
        <button v-for="category in catalog?.categories" :key="category.id" :class="{active:selectedCategory===category.id}" type="button" @click="selectedCategory=category.id">
          <span>{{ categoryIcon(category.id) }}</span><div><strong>{{ category.title }}</strong><small>{{ category.description }}</small></div>
        </button>
      </nav>
      <div class="account-tutorial-heading"><div><strong>{{ currentCategory?.title }}</strong><small>{{ currentCategory?.description }}</small></div><span>{{ filteredTutorials.length }} 节</span></div>
      <div class="account-tutorial-grid">
        <article v-for="(tutorial,index) in filteredTutorials" :key="tutorial.id">
          <span class="account-tutorial-index">{{ String(index+1).padStart(2,"0") }}</span>
          <div class="account-tutorial-copy"><div><em>{{ tutorial.level }}</em><small>{{ tutorial.duration }}</small></div><h3>{{ tutorial.title }}</h3><p>{{ tutorial.summary }}</p><div class="account-tutorial-points"><span v-for="point in tutorial.points" :key="point">{{ point }}</span></div><aside><strong>课后小任务</strong><span>{{ tutorial.challenge }}</span></aside></div>
          <button class="primary account-tutorial-start" type="button" :disabled="opening===tutorial.id" @click="openTutorial(tutorial)"><svg viewBox="0 0 24 24"><path d="m9 7 8 5-8 5z"/></svg>{{ opening===tutorial.id?'正在打开':'开始教程' }}</button>
        </article>
      </div>
    </template>
  </section>
  <StoryPlayer v-if="activeArchive" :show="playerOpen" :archive="activeArchive" :asset-url="tutorialAssetUrl" playback-only auto-start teach-manual-advance @change="activeArchive=$event" @complete="tutorialComplete=true" @close="closePlayer" />
  <Teleport to="body"><Transition name="account-tutorial-complete"><div v-if="tutorialComplete" class="account-tutorial-complete"><section role="dialog" aria-modal="true"><small>基本使用教程</small><h2>“{{ activeTutorial?.title }}”播放完成</h2><p>做得好。你可以继续学习，也可以回到账号中心的其他页面。</p><footer><button type="button" @click="closePlayer">继续选教程</button><button class="primary" type="button" @click="returnToDocuments">返回我的文档</button></footer></section></div></Transition></Teleport>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from "vue";
import { readStoryPackage } from "~/story/package";
import type { StoryArchive, StoryAssetRef } from "~/story/types";
import StoryPlayer from "./StoryPlayer.vue";
interface TutorialCategory { id:string;title:string;description:string }
interface TutorialItem { id:string;category:string;title:string;summary:string;duration:string;level:string;points:string[];challenge:string;file:string }
interface TutorialCatalog { version:number;categories:TutorialCategory[];tutorials:TutorialItem[] }
const emit=defineEmits<{leave:[]}>();
const catalog=ref<TutorialCatalog>();const loading=ref(false);const error=ref("");const selectedCategory=ref("start");const opening=ref("");
const activeArchive=ref<StoryArchive>();const activeTutorial=ref<TutorialItem>();const playerOpen=ref(false);const tutorialComplete=ref(false);const objectUrls=new Map<string,string>();
const currentCategory=computed(()=>catalog.value?.categories.find(item=>item.id===selectedCategory.value));
const filteredTutorials=computed(()=>catalog.value?.tutorials.filter(item=>item.category===selectedCategory.value)||[]);
const icons:Record<string,string>={start:"✦",edit:"✎",performance:"▶",effects:"✺"};const categoryIcon=(id:string)=>icons[id]||"•";
async function loadCatalog(){loading.value=true;error.value="";try{const response=await fetch("/tutorials/catalog.json",{cache:"no-store"});if(!response.ok)throw new Error(`目录请求失败（${response.status}）`);catalog.value=await response.json();if(!catalog.value?.categories.length||!catalog.value.tutorials.length)throw new Error("教程目录为空");if(!catalog.value.categories.some(item=>item.id===selectedCategory.value))selectedCategory.value=catalog.value.categories[0].id}catch(exception){error.value=exception instanceof Error?exception.message:"无法读取教程目录"}finally{loading.value=false}}
async function openTutorial(tutorial:TutorialItem){opening.value=tutorial.id;error.value="";try{const response=await fetch(`/tutorials/${encodeURIComponent(tutorial.file)}`,{cache:"no-store"});if(!response.ok)throw new Error(`教程文件请求失败（${response.status}）`);activeArchive.value=await readStoryPackage(await response.blob());activeTutorial.value=tutorial;tutorialComplete.value=false;playerOpen.value=true}catch(exception){error.value=exception instanceof Error?exception.message:"无法打开教程"}finally{opening.value=""}}
function clearObjectUrls(){for(const url of objectUrls.values())URL.revokeObjectURL(url);objectUrls.clear()}
function closePlayer(){tutorialComplete.value=false;playerOpen.value=false;activeArchive.value=undefined;activeTutorial.value=undefined;clearObjectUrls()}
function returnToDocuments(){closePlayer();emit("leave")}
function tutorialAssetUrl(id:string){const existing=objectUrls.get(id);if(existing)return existing;const archive=activeArchive.value;const bytes=archive?.assets.get(id);if(!archive||!bytes)return id;const refs:StoryAssetRef[]=[...(archive.document.characters.map(item=>item.avatar).filter(Boolean) as StoryAssetRef[]),...archive.document.messages.flatMap(item=>item.kind==="text"?[]:[item.asset])];const url=URL.createObjectURL(new Blob([bytes],{type:refs.find(item=>item.id===id)?.mime||"application/octet-stream"}));objectUrls.set(id,url);return url}
onMounted(loadCatalog);onBeforeUnmount(clearObjectUrls);
</script>

