ding small,.account-tutorial-heading>span{color:var(--muted-text);font-size:.72rem}.account-tutorial-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.7rem}.account-tutorial-grid article{display:grid;grid-template-columns:38px minmax(0,1fr);grid-template-rows:minmax(0,1fr) 38px;gap:.65rem;border:1px solid var(--control-border);border-radius:15px;padding:.85rem;background:var(--panel-surface)}.account-tutorial-index{display:grid;width:34px;height:34px;place-items:center;border-radius:10px;background:var(--selected-bg);color:var(--focus-color);font-size:.72rem;font-weight:800}.account-tutorial-copy{min-width:0}.account-tutorial-copy>div{display:flex;align-items:center;gap:.45rem}.account-tutorial-copy em{border-radius:99px;padding:.1rem .38rem;background:var(--control-surface);color:var(--focus-color);font-size:.65rem;font-style:normal}.account-tutorial-copy small,.account-tutorial-copy p{color:var(--muted-text)}.account-tutorial-copy h3{margin:.35rem 0 .2rem}.account-tutorial-copy p{margin:0;font-size:.76rem}.account-tutorial-points{display:flex!important;gap:.3rem!important;flex-wrap:wrap;margin-top:.5rem}.account-tutorial-points span{border:1px solid var(--control-border);border-radius:6px;padding:.12rem .32rem;color:var(--muted-text);font-size:.63rem}.account-tutorial-copy aside{display:grid;gap:.12rem;margin-top:.55rem;border-left:3px solid var(--focus-color);border-radius:0 8px 8px 0;padding:.38rem .5rem;background:var(--selected-bg);font-size:.67rem}.account-tutorial-copy aside strong{color:var(--focus-color)}.account-tutorial-start{display:flex;grid-column:1/-1;align-items:center;justify-content:center;gap:.3rem;width:100%;min-height:38px;border:0;border-radius:9px}.account-tutorial-start svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.8}.account-tutorial-state{display:grid;min-height:260px;place-content:center;justify-items:center;gap:.6rem;color:var(--muted-text)}.account-tutorial-state i{width:26px;height:26px;bord