.account-tutorial-page{max-width:1220px;padding:1.15rem 1.3rem 2rem}.account-tutorial-start{border:1px solid var(--primary-bg);background:var(--primary-bg);color:var(--primary-text);font:inherit;font-size:.78rem;font-weight:700;cursor:pointer;transition:filter .15s ease,transform .15s ease}.account-tutorial-start:hover{filter:brightness(1.08)}.account-tutorial-start:active{transform:translateY(1px)}.account-tutorial-start:disabled{opacity:.58;cursor:wait}
@media(max-width:760px){.account-tutorial-intro{padding:.85rem}.account-tutorial-progress{min-width:62px}.account-tutorial-categories{display:flex;overflow-x:auto;padding-bottom:.15rem;scrollbar-width:none}.account-tutorial-categories button{min-width:150px}.account-tutorial-grid{grid-template-columns:1fr}.account-tutorial-complete{place-items:stretch;padding:0}.account-tutorial-complete section{display:grid;width:100%;height:100%;align-content:center;border:0;border-radius:0;padding:max(1rem,env(safe-area-inset-top)) 1rem max(1rem,env(safe-area-inset-bottom))}}
